    lat2 = Math.toRadians(cLat);
    havLat = 1 - Math.cos(lat1 - lat2);
    havLon = 1 - Math.cos(Math.toRadians(aLon - cLon));
    double acSortKey =
        Double.longBitsToDouble(
            Double.doubleToRawLongBits(havLat + Math.cos(lat1) * Math.cos(lat2) * havLon)
                & 0xFFFFFFFFFFFFFFF8L);

    final int encodedOrientation = GeoUtils.orient(aX, aY, bX, bY, cX, cY);
    final GeoUtils.WindingOrder winding = GeoUtils.WindingOrder.fromSign(encodedOrientation);
    final boolean abSame = aX == bX && aY == bY;
    final boolean acSame = aX == cX && aY == cY;
    final boolean bcSame = bX == cX && bY == cY;

    if (abSame) {
      if (acSame) {
        triangle.type = DecodedTriangle.TYPE.POINT;
      } else {
        boolean collapsedInside = Tessellator.pointInTriangle(cX, cY, aX, aY, bX, bY, cX, cY);
