        triangle.bX = triangle.cX;
        triangle.bY = triangle.cY;
        triangle.cX = triangle.aX;
        triangle.cY = triangle.aY;
      }
    } else if (acSame) {
      boolean retainedInside = Tessellator.pointInTriangle(bX, bY, aX, aY, bX, bY, cX, cY);
      if (retainedInside || abSortKey > 0.0 || mortonA == mortonC) {
