  final int aY = triangle.aY;
  final int bX = triangle.bX;
  final int bY = triangle.bY;
  final int cX = triangle.cX;
  final int cY = triangle.cY;

  long evenA = aX & 0xFFFFFFFFL;
  long oddA = aY & 0xFFFFFFFFL;
  evenA = (evenA | (evenA << 16)) & 0x0000FFFF0000FFFFL;
  evenA = (evenA | (evenA << 8)) & 0x00FF00FF00FF00FFL;
  evenA = (evenA | (evenA << 4)) & 0x0F0F0F0F0F0F0F0FL;
  evenA = (evenA | (evenA << 2)) & 0x3333333333333333L;
  evenA = (evenA | (evenA << 1)) & 0x5555555555555555L;
  oddA = (oddA | (oddA << 16)) & 0x0000FFFF0000FFFFL;
  oddA = (oddA | (oddA << 8)) & 0x00FF00FF00FF00FFL;
  oddA = (oddA | (oddA << 4)) & 0x0F0F0F0F0F0F0F0FL;
  oddA = (oddA | (oddA << 2)) & 0x3333333333333333L;
